INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('bay-area-happy-trip', 'bay-area-happy-trip', '湾区开心游', 'travel-local-life', 'running', '进行中 / Live', '构建大湾区旅行、游玩伴随 Agent,像你身边手头的旅行达人和本地精英,让用户无所不知、玩得尽兴。', '让 Agent 能理解用户偏好、实时位置、预算、交通、天气和本地文化,生成可信、好玩、可执行的旅行陪伴方案。', '{"registration": "已结束", "race": "进行中", "submission": "开放中", "judging": "排队中", "results": "未发布"}'::jsonb, '{"riders": 36, "activeRiders": 27, "sessions": 188, "submittedWorks": 14, "publicWorks": 0, "reports": 0, "evidenceRefs": 206}'::jsonb, '{"stageLabel": "进行中 / Live", "primaryCta": "进入 Live Hall", "secondaryCta": "查看参赛作品", "heroUse": "Home featured race / Live Hall / Screen Display", "awards": ["最佳旅行体验", "最佳本地洞察", "最佳实时规划", "最佳游玩复盘"], "live": {"ridingSignal": 82, "submitLeft": "02:18:44", "totalCost": "$512.70", "riskSignals": 5, "costWatchRiders": 3}, "featured": true}'::jsonb, false, '2026-05-10T13:58:00+08:00', NULL);
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('smart-investment-analyst', 'smart-investment-analyst', '智能投研助理', 'finance', 'running', '进行中 / Live', '面向个人投资学习者的资料整理、术语解释、公司信息摘要和风险提示 Agent。', '构建能帮助用户理解金融材料、整理风险点和形成学习笔记的投研辅助 Agent,不替代专业投资建议。', '{"registration": "已结束", "race": "进行中", "submission": "开放中", "judging": "排队中", "results": "未发布"}'::jsonb, '{"riders": 28, "activeRiders": 21, "sessions": 164, "submittedWorks": 9, "publicWorks": 0, "reports": 0, "evidenceRefs": 171}'::jsonb, '{"stageLabel": "进行中 / Live", "primaryCta": "进入 Live Hall", "secondaryCta": "查看风险提示样例", "heroUse": "Hero live switcher secondary race / Risk-heavy Live Hall variant", "awards": ["最佳风险表达", "最佳资料整理", "最佳学习笔记"], "live": {"ridingSignal": 76, "submitLeft": "03:02:10", "totalCost": "$438.20", "riskSignals": 8, "costWatchRiders": 2}, "safetyNotes": ["只做信息整理、术语解释和风险提示;不输出直接买卖建议。"]}'::jsonb, true, '2026-05-10T13:58:00+08:00', NULL);
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('media-ops-agent', 'media-ops-agent', '自媒体运营 Agent', 'content-ops', 'judging', '评审中', '开发一款可帮助主人规划选题、生成内容、发布排期、复盘数据和维护品牌语气的自媒体运营 Agent。', '让 Agent 像运营助理一样持续协助内容生产和复盘,而不是只生成一次文案。', '{"registration": "已结束", "race": "已完成", "submission": "已锁定", "judging": "进行中", "results": "待发布"}'::jsonb, '{"riders": 32, "activeRiders": 0, "sessions": 219, "submittedWorks": 27, "publicWorks": 0, "reports": 0, "evidenceRefs": 238}'::jsonb, '{"stageLabel": "评审中", "primaryCta": "查看评审进度", "secondaryCta": "查看提交作品", "heroUse": "Judge View / Works / Review draft", "awards": ["最佳运营闭环", "最佳品牌语气", "最佳数据复盘"]}'::jsonb, false, '2026-05-10T13:58:00+08:00', NULL);
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('merchant-copilot', 'merchant-copilot', '网商经营 Copilot', 'e-commerce', 'registration', '报名中', '帮助小商家做选品、上架、客服、促销、复盘和库存提醒的网商经营 Agent。', '让 Agent 成为小店主的运营副驾,能把商品、客户、内容和经营指标串起来。', '{"registration": "开放中", "race": "未开始", "submission": "未开始", "judging": "未开始", "results": "未发布"}'::jsonb, '{"riders": 0, "applicants": 41, "capacity": 60, "sessions": 0, "submittedWorks": 0}'::jsonb, '{"stageLabel": "报名中", "primaryCta": "立即报名", "secondaryCta": "查看赛题", "heroUse": "Registration Open / Home CTA", "awards": ["最佳经营闭环", "最佳客服体验", "最佳上架自动化"]}'::jsonb, false, '2026-05-10T13:58:00+08:00', NULL);
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('health-habit-coach', 'health-habit-coach', '健康习惯教练', 'health', 'registration', '报名中', '帮助用户制定运动、睡眠、饮食和复盘计划的健康习惯陪伴 Agent。', '构建一个长期陪伴型 Agent,帮助用户记录目标、跟踪习惯、生成反馈,但不提供医疗诊断。', '{"registration": "开放中", "race": "未开始", "submission": "未开始", "judging": "未开始", "results": "未发布"}'::jsonb, '{"riders": 0, "applicants": 33, "capacity": 50, "sessions": 0, "submittedWorks": 0}'::jsonb, '{"stageLabel": "报名中", "primaryCta": "立即报名", "secondaryCta": "查看安全边界", "heroUse": "Registration Open / Public conversion", "safetyNotes": ["只做习惯记录、计划建议和反馈提醒;不做诊断或治疗建议。"]}'::jsonb, true, '2026-05-10T13:58:00+08:00', NULL);
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('gov-service-navigator', 'gov-service-navigator', '政务办事导航 Agent', 'e-government', 'completed', '已结束 / 赛果已发布', '帮助居民理解办事流程、材料清单、办理条件和进度提醒的政务流程导航 Agent。', '把复杂政策流程转成清晰、可信、可执行的办事导航,不代办敏感事项。', '{"registration": "已结束", "race": "已完成", "submission": "已锁定", "judging": "已完成", "results": "已发布"}'::jsonb, '{"riders": 24, "activeRiders": 0, "sessions": 137, "submittedWorks": 19, "publicWorks": 12, "reports": 24, "evidenceRefs": 148}'::jsonb, '{"stageLabel": "已结束 / 赛果已发布", "primaryCta": "查看赛果", "secondaryCta": "查看 Review", "heroUse": "Latest Results / Serious-domain case", "awards": ["最佳可信流程", "最佳材料清单", "最佳进度提醒"], "safetyNotes": ["只做流程导航和材料清单辅助;不替代官方办理和最终审核。"]}'::jsonb, true, '2026-05-10T13:58:00+08:00', NULL);
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('genesis-dogfood-race', 'genesis-dogfood-race', '创世骑行挑战赛', 'self-dogfood', 'archived', '创世案例 / 已归档', '参赛者骑行 Coding Agent 打造 ARY 的第一场创世赛,从混乱起跑到作品冲线,形成平台自己的开场故事;现已归档为创世资产。', '用 Agent 协作开发 ARY 自身,让平台从第一场 self-dogfood Race 中诞生。', '{"registration": "已结束", "race": "已完成", "submission": "已锁定", "judging": "已完成", "results": "已发布(已归档)"}'::jsonb, '{"riders": 18, "activeRiders": 0, "sessions": 143, "submittedWorks": 12, "publicWorks": 8, "reports": 18, "evidenceRefs": 164}'::jsonb, '{"stageLabel": "创世案例 / 已归档", "primaryCta": "查看创世复盘", "secondaryCta": "查看优秀作品", "heroUse": "Archived genesis asset / Results / Review / Rider Profile", "awards": ["最佳自举作品", "最佳领域拆解", "最佳复盘"], "notes": ["归档赛事,仍保留已发布的公开资产;不作为 running 主赛事。"]}'::jsonb, false, '2026-05-10T13:58:00+08:00', '2026-05-30T12:00:00+08:00');
INSERT INTO core.races (id, slug, title, domain, status, stage_label, summary, challenge, schedule, metrics, display, safety_sensitive, created_at, archived_at) VALUES ('medical-followup-assistant', 'medical-followup-assistant', '医疗随访助手', 'medical', 'upcoming', '即将开放 / 高敏边界', '帮助患者整理随访问题、用药提醒、复诊材料和健康记录的医疗随访辅助 Agent。', '在高敏场景中训练 Agent 的解释边界、记录能力和低风险辅助,不做诊断。', '{"registration": "即将开放", "race": "未开始", "submission": "未开始", "judging": "未开始", "results": "未发布"}'::jsonb, '{"riders": 0, "watchers": 96, "capacity": 40, "sessions": 0, "submittedWorks": 0}'::jsonb, '{"stageLabel": "即将开放 / 高敏边界", "primaryCta": "订阅开放提醒", "secondaryCta": "查看安全说明", "heroUse": "Upcoming / Safety-boundary example / Empty-riding sample", "safetyNotes": ["不做诊断;不替代医生;只做随访准备、提醒和记录整理。"]}'::jsonb, true, '2026-05-10T13:58:00+08:00', NULL);
